<?php
$error=null;$role=role_name();$doctorSelf=doctor_for_current_user();$selectedDoctor=has_role('Doctor')?(int)($doctorSelf['doctor_id']??0):(int)($_GET['doctor_id']??$_POST['doctor_id']??0);$date=get_string('date',date('Y-m-d'));
if(request_method('POST')){try{verify_csrf();$action=post_string('action');$appointmentId=(int)($_POST['appointment_id']??0);$stmt=db()->prepare('SELECT a.*,p.full_name patient_name FROM appointments a JOIN patients p ON p.patient_id=a.patient_id WHERE a.appointment_id=?');$stmt->execute([$appointmentId]);$app=$stmt->fetch();if(!$app)throw new RuntimeException('Appointment not found.');if(has_role('Doctor')&&(int)$app['doctor_id']!==(int)$doctorSelf['doctor_id'])throw new RuntimeException('This patient is not assigned to you.');if($action==='checkin'){require_roles(['Admin','Receptionist']);if(!in_array($app['status'],['Confirmed','Pending'],true))throw new RuntimeException('Only pending or confirmed appointments can be checked in.');if($app['appointment_date']!==date('Y-m-d'))throw new RuntimeException('Patients can only be checked in on the appointment date.');$pdo=db();$pdo->beginTransaction();$doctorLock=$pdo->prepare('SELECT doctor_id FROM doctors WHERE doctor_id=? FOR UPDATE');$doctorLock->execute([$app['doctor_id']]);$stmt=$pdo->prepare('SELECT q.token_id FROM queue_tokens q JOIN appointments a ON a.appointment_id=q.appointment_id WHERE a.doctor_id=? AND a.appointment_date=? FOR UPDATE');$stmt->execute([$app['doctor_id'],$app['appointment_date']]);$position=count($stmt->fetchAll())+1;$token='D'.$app['doctor_id'].'-'.str_pad((string)$position,2,'0',STR_PAD_LEFT);$pdo->prepare("INSERT INTO queue_tokens (appointment_id,token_number,check_in_time,queue_position,queue_status) VALUES (?,?,NOW(),?,'Waiting') ON DUPLICATE KEY UPDATE check_in_time=VALUES(check_in_time),queue_position=VALUES(queue_position),queue_status='Waiting'")->execute([$appointmentId,$token,$position]);$pdo->prepare("UPDATE appointments SET status='Checked In' WHERE appointment_id=?")->execute([$appointmentId]);$pdo->commit();notify_user(find_patient_user_id((int)$app['patient_id']),'Checked in','Your queue token is '.$token.'.','Queue','queue',$appointmentId);log_action('CHECK_IN','appointments',$appointmentId,null,['token'=>$token]);flash('queue','Patient checked in with token '.$token.'.','success');redirect_to('queue',['doctor_id'=>$app['doctor_id'],'date'=>$app['appointment_date']]);}
if($action==='start'){require_roles(['Admin','Doctor']);if(!in_array($app['status'],['Checked In','Waiting'],true))throw new RuntimeException('The patient must be checked in before consultation.');if($app['appointment_date']!==date('Y-m-d'))throw new RuntimeException('Consultations can only be started on the appointment date.');$pdo=db();$pdo->beginTransaction();$doctorLock=$pdo->prepare('SELECT doctor_id FROM doctors WHERE doctor_id=? FOR UPDATE');$doctorLock->execute([$app['doctor_id']]);$tokenStmt=$pdo->prepare('SELECT token_id FROM queue_tokens WHERE appointment_id=? FOR UPDATE');$tokenStmt->execute([$appointmentId]);if(!$tokenStmt->fetchColumn())throw new RuntimeException('The queue token is missing. Check the patient in again.');$activeStmt=$pdo->prepare("SELECT q.token_id FROM queue_tokens q JOIN appointments a ON a.appointment_id=q.appointment_id WHERE a.doctor_id=? AND a.appointment_date=? AND q.queue_status='In Consultation' AND a.appointment_id<>? FOR UPDATE");$activeStmt->execute([$app['doctor_id'],$app['appointment_date'],$appointmentId]);if($activeStmt->fetchColumn())throw new RuntimeException('This doctor already has a consultation in progress. Complete it before starting the next patient.');$pdo->prepare("UPDATE appointments SET status='In Consultation' WHERE appointment_id=?")->execute([$appointmentId]);$pdo->prepare("UPDATE queue_tokens SET queue_status='In Consultation',consultation_start_time=NOW() WHERE appointment_id=?")->execute([$appointmentId]);$pdo->commit();log_action('START_CONSULTATION','appointments',$appointmentId);redirect_to('consultations',['appointment_id'=>$appointmentId]);}
if($action==='noshow'){require_roles(['Admin','Receptionist']);if(!in_array($app['status'],['Confirmed','Checked In'],true))throw new RuntimeException('Only confirmed or checked-in appointments can be marked no-show.');if($app['appointment_date']>date('Y-m-d'))throw new RuntimeException('A future appointment cannot be marked no-show.');db()->prepare("UPDATE appointments SET status='No-show' WHERE appointment_id=?")->execute([$appointmentId]);db()->prepare("UPDATE queue_tokens SET queue_status='No-show' WHERE appointment_id=?")->execute([$appointmentId]);notify_user(find_patient_user_id((int)$app['patient_id']),'Appointment marked no-show',$app['appointment_number'].' was marked as no-show.','Appointment','appointments',$appointmentId);flash('queue','Appointment marked no-show.','success');redirect_to('queue',['doctor_id'=>$app['doctor_id'],'date'=>$app['appointment_date']]);}}
catch(Throwable $e){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$doctors=has_role(['Admin','Receptionist'])?db()->query("SELECT d.doctor_id,u.full_name FROM doctors d JOIN users u ON u.user_id=d.user_id WHERE d.status='Active' ORDER BY u.full_name")->fetchAll():[];if($selectedDoctor<1&&$doctors)$selectedDoctor=(int)$doctors[0]['doctor_id'];$params=[$date];$where='a.appointment_date=?';if($selectedDoctor){$where.=' AND a.doctor_id=?';$params[]=$selectedDoctor;}$stmt=db()->prepare("SELECT a.*,p.patient_code,p.full_name patient_name,p.phone,u.full_name doctor_name,q.token_number,q.queue_status,q.check_in_time,TIMESTAMPDIFF(MINUTE,q.check_in_time,NOW()) waiting_minutes FROM appointments a JOIN patients p ON p.patient_id=a.patient_id JOIN doctors d ON d.doctor_id=a.doctor_id JOIN users u ON u.user_id=d.user_id LEFT JOIN queue_tokens q ON q.appointment_id=a.appointment_id WHERE $where AND a.status NOT IN ('Cancelled') ORDER BY CASE WHEN q.queue_status='In Consultation' THEN 0 WHEN q.queue_status='Waiting' THEN 1 ELSE 2 END,a.start_time");$stmt->execute($params);$rows=$stmt->fetchAll();$avg=$selectedDoctor?(int)query_value('SELECT average_consultation_minutes FROM doctors WHERE doctor_id=?',[$selectedDoctor]):15;$activeConsultations=count(array_filter($rows,fn($r)=>($r['queue_status']??'')==='In Consultation'));$waitingIndex=0;
?>
<div class="page-header"><div><h2>Patient queue</h2><p>Check-in, token assignment and live consultation flow.</p></div><div class="actions"><button class="btn btn-light" onclick="location.reload()">↻ Refresh</button></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card mb-2"><form method="get" class="actions"><input type="hidden" name="page" value="queue"><?php if($doctors):?><select class="select" style="max-width:280px" name="doctor_id"><?php foreach($doctors as $d):?><option value="<?=$d['doctor_id']?>" <?=$selectedDoctor===$d['doctor_id']?'selected':''?>><?=e($d['full_name'])?></option><?php endforeach;?></select><?php endif;?><input class="input" style="max-width:190px" type="date" name="date" value="<?=e($date)?>"><button class="btn btn-primary">Open queue</button></form></div>
<div class="grid grid-4 mb-2"><div class="card stat-card" style="--stat-color:#2563eb"><div><div class="stat-label">Appointments</div><div class="stat-value"><?=count($rows)?></div><div class="stat-note"><?=format_date($date)?></div></div><div class="stat-icon">◷</div></div><div class="card stat-card" style="--stat-color:#d97706"><div><div class="stat-label">Waiting</div><div class="stat-value"><?=count(array_filter($rows,fn($r)=>($r['queue_status']??'')==='Waiting'))?></div><div class="stat-note">Checked-in patients</div></div><div class="stat-icon">≡</div></div><div class="card stat-card" style="--stat-color:#0284c7"><div><div class="stat-label">In consultation</div><div class="stat-value"><?=count(array_filter($rows,fn($r)=>($r['queue_status']??'')==='In Consultation'))?></div><div class="stat-note">Current patient</div></div><div class="stat-icon">✚</div></div><div class="card stat-card" style="--stat-color:#15803d"><div><div class="stat-label">Completed</div><div class="stat-value"><?=count(array_filter($rows,fn($r)=>$r['status']==='Completed'))?></div><div class="stat-note">Finished visits</div></div><div class="stat-icon">✓</div></div></div>
<div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Token</th><th>Patient</th><th>Appointment</th><th>Check-in</th><th>Estimated wait</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><?php if(($r['queue_status']??'')==='Waiting')$waitingIndex++;?><tr class="<?=($r['queue_status']??'')==='In Consultation'?'queue-current':''?>"><td><strong class="queue-token" style="font-size:20px"><?=e($r['token_number']??'—')?></strong></td><td><div class="table-title"><?=e($r['patient_name'])?></div><div class="table-subtitle"><?=e($r['patient_code'])?> · <?=e($r['phone'])?></div></td><td><?=format_time($r['start_time'])?><div class="table-subtitle"><?=e($r['appointment_number'])?></div></td><td><?=format_time($r['check_in_time'])?></td><td><?php if(($r['queue_status']??'')==='Waiting'):?>~<?=max(0,($waitingIndex-1+$activeConsultations)*$avg)?> min<?php else:?>—<?php endif;?></td><td><span class="badge badge-<?=status_class($r['queue_status']??$r['status'])?>"><?=e($r['queue_status']??$r['status'])?></span></td><td><div class="actions"><?php if(has_role(['Admin','Receptionist'])&&in_array($r['status'],['Pending','Confirmed'],true)):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="checkin"><input type="hidden" name="appointment_id" value="<?=$r['appointment_id']?>"><button class="btn btn-primary btn-sm">Check in</button></form><?php endif;?><?php if(has_role(['Admin','Doctor'])&&in_array($r['status'],['Checked In','Waiting'],true)):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="start"><input type="hidden" name="appointment_id" value="<?=$r['appointment_id']?>"><button class="btn btn-secondary btn-sm">Start</button></form><?php endif;?><?php if(has_role(['Admin','Receptionist'])&&in_array($r['status'],['Confirmed','Checked In'],true)):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="noshow"><input type="hidden" name="appointment_id" value="<?=$r['appointment_id']?>"><button class="btn btn-warning btn-sm">No-show</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></div>
